import pandas as pd

def safe_len(v):
    return 0 if pd.isna(v) else len(v)

def calculate(pdf):
    FLOW_RANK_lag1 = 0
    rows = []
    for _, row in pdf.iterrows():


        FLOW_RANK_new = int(FLOW_RANK_lag1 + 1)

        FLOW_RANK_lag1 = FLOW_RANK_new
        newRow = row.copy()
        newRow["FLOW_RANK"] = FLOW_RANK_new
        rows.append(newRow)

    if not rows:
        empty = pdf.iloc[0:0].copy()
        if "FLOW_RANK" not in empty.columns:
            empty["FLOW_RANK"] = pd.Series(dtype="object")
        return empty

    return pd.DataFrame(rows)



